// Rewrites dist/server/wrangler.json (generated by vinext for OpenAI Sites)
// for direct Cloudflare deployment on the naibul.com zone.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { resolve, dirname } from "node:path";

const path = resolve(dirname(fileURLToPath(import.meta.url)), "../dist/server/wrangler.json");
const config = JSON.parse(await readFile(path, "utf8"));

config.topLevelName = "ashen";
config.name = "ashen";
config.account_id = "e6253033b602dbb1445f44393ea7da2b";
config.d1_databases = [
  { binding: "DB", database_name: "ashen", database_id: "0ca81687-6c20-4765-a2df-697d6885769b" },
];
config.images = { binding: "IMAGES" };
config.assets = { ...config.assets, binding: "ASSETS" };
config.routes = [{ pattern: "ashen.naibul.com", custom_domain: true }];

await writeFile(path, JSON.stringify(config, null, 2) + "\n");
console.log("patched", path);
